using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1: EF Core 9 renamed the discriminator JSON property
            // from "Discriminator" to "$type". Existing 500K documents and direct SQL
            // queries (c.Discriminator = 'Product') require the old name.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2: EF Core 9 changed the Cosmos `id` value format
            // from "Product|123" to just "123". Existing documents would become
            // unreachable. Map a shadow property to preserve the old format.
            entity.Property<string>("__id")
                  .ToJsonPropertyName("id")
                  .HasValueGenerator<LegacyCosmosIdGenerator>();

            // BREAKING CHANGE 3: HasIndex() now throws for the Cosmos provider
            // (it was silently ignored in EF Core 8). Removed.
        });
    }
}

/// <summary>
/// Reproduces the EF Core 8 id format: "EntityType|KeyValue"
/// so that existing Cosmos documents remain addressable.
/// </summary>
class LegacyCosmosIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;

    protected override string NextValue(EntityEntry entry)
    {
        var entityType = entry.Metadata.ShortName();
        var pk = entry.Property("Id").CurrentValue;
        return $"{entityType}|{pk}";
    }
}

class Product
{
    public int Id { get; set; }
    public string Sku { get; set; }
}

